// Types for generated data models — generated by `mcn build --target flutter`.

class RefInfo {
  const RefInfo({required this.resource, required this.label, required this.list, this.labelField});

  final String resource;
  final String label;
  final String list;
  final String? labelField;
}

class Field {
  const Field({
    required this.name,
    required this.label,
    required this.type,
    this.required = false,
    this.choices = const [],
    this.pluralLabel,
    this.ref,
    this.defaultValue,
    this.readRoles = const [],
    this.writeRoles = const [],
  });

  final String name;
  final String label;
  final String type;
  final bool required;
  final List<String> choices;
  final String? pluralLabel;
  final RefInfo? ref;
  final Object? defaultValue;
  final List<String> readRoles;
  final List<String> writeRoles;
}

class Resource {
  const Resource({
    required this.name,
    required this.label,
    required this.plural,
    required this.endpoints,
    required this.fields,
  });

  final String name;
  final String label;
  final String plural;
  final Map<String, String> endpoints;
  final List<Field> fields;

  /// The field that names a record (name / title / … or the first text field).
  Field? get labelField {
    for (final key in const ['name', 'title', 'label', 'email']) {
      for (final f in fields) {
        if (f.name == key && (f.type == 'str' || f.type == 'string')) return f;
      }
    }
    for (final f in fields) {
      if (f.type == 'str' || f.type == 'string') return f;
    }
    return null;
  }
}
